css:
.dcw-block { margin-top: clamp(48px, 6vw, 88px); }
.dcw-col { display: flex; flex-direction: column; align-items: flex-start; }
.dcw-split { display: grid; grid-template-columns: 5fr 7fr; grid-column-gap: clamp(28px, 5vw, 72px); grid-row-gap: 32px; align-items: start; }
.dcw-head { max-width: 760px; margin-bottom: clamp(32px, 5vw, 56px); }
.dcw-eyebrow-num { display: flex; justify-content: center; align-items: center; min-width: 28px; height: 28px; padding-left: 6px; padding-right: 6px; border-radius: 999px; background-color: #0f6e68; color: #ffffff; font-size: 12px; font-weight: 700; letter-spacing: 0; }
.dcw-h2 { margin-top: 0; margin-bottom: 0; font-family: Poppins, sans-serif; color: #111111; font-size: clamp(30px, 3.6vw, 44px); line-height: 1.15; font-weight: 600; letter-spacing: -0.02em; }
.dcw-h2-bar { width: 56px; height: 4px; margin-top: 18px; border-radius: 4px; background-image: linear-gradient(90deg, #0f6e68, #2fb3a6); }
.dcw-h3 { margin-top: 0; margin-bottom: 12px; font-family: Inter, sans-serif; color: #111111; font-size: clamp(20px, 2vw, 24px); line-height: 1.25; font-weight: 600; letter-spacing: -0.01em; }
.dcw-h4 { margin-top: 0; margin-bottom: 12px; font-family: Inter, sans-serif; color: #111111; font-size: 18px; line-height: 1.3; font-weight: 600; letter-spacing: 0; }
.dcw-p.is-measure { max-width: 66ch; }
.dcw-p.is-spaced { margin-top: 16px; }
.dcw-strong { color: #111111; font-weight: 600; }
.dcw-kicker { margin-bottom: 8px; color: #5f5f5f; font-size: 13px; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; }
.dcw-kicker.is-spaced { margin-top: 28px; }
.dcw-caption { margin-top: 14px; margin-bottom: 0; color: #5f5f5f; font-size: 14px; line-height: 1.5; }
.dcw-ul { margin-top: 0; margin-bottom: 0; padding-left: 20px; }
.dcw-li { margin-bottom: 6px; color: #3d3d3d; font-size: 16px; line-height: 1.55; }
.dcw-pills { display: flex; flex-wrap: wrap; grid-column-gap: 8px; grid-row-gap: 8px; }
.dcw-statement { margin-top: 0; margin-bottom: 24px; padding-left: 20px; border-left: 4px solid #0f6e68; color: #111111; font-size: clamp(20px, 2.2vw, 26px); line-height: 1.4; }
.dcw-meta { display: flex; flex-direction: column; }
.dcw-meta-row { display: grid; grid-template-columns: 150px 1fr; grid-column-gap: 12px; padding-top: 16px; padding-bottom: 16px; border-bottom: 1px solid #e2e2e2; }
.dcw-meta-k { padding-top: 2px; color: #5f5f5f; font-size: 13px; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase; }
.dcw-meta-v { color: #111111; font-size: 16px; }
.dcw-role-cols { display: grid; grid-template-columns: 1fr 1fr; grid-column-gap: 32px; grid-row-gap: 24px; margin-top: 24px; }
.dcw-role-card { padding: clamp(20px, 3vw, 32px); border: 1px solid #e2e2e2; border-radius: 14px; background-color: #f6f6f5; }
.dcw-role-card.is-mine { border-color: transparent; background-image: linear-gradient(160deg, #e3f2ef, #d2ebe5); }
.dcw-timeline { display: grid; grid-template-columns: repeat(5, 1fr); grid-column-gap: 8px; padding-top: 12px; }
.dcw-tl { position: relative; padding: 14px 14px 16px; border-radius: 10px; background-color: #f6f6f5; }
.dcw-tl.is-mine { background-image: linear-gradient(160deg, #e3f2ef, #d2ebe5); }
.dcw-tl.is-lead { background-image: linear-gradient(160deg, #0f6e68, #0a524e); }
.dcw-tl-h { color: #5f5f5f; font-size: 15px; font-weight: 600; }
.dcw-tl-h.is-mine { color: #0a524e; }
.dcw-tl-h.is-lead { color: #ffffff; }
.dcw-tl-t { color: #5f5f5f; font-size: 13.5px; line-height: 1.4; }
.dcw-tl-t.is-mine { color: #3d3d3d; }
.dcw-tl-t.is-lead { color: rgba(255,255,255,0.88); }
.dcw-tl-join { position: absolute; left: 12px; top: -10px; padding: 2px 8px; border-radius: 999px; background-color: #0f6e68; color: #ffffff; font-size: 11px; font-weight: 600; letter-spacing: 0.05em; text-transform: uppercase; }
@media screen and (max-width: 991px) { .dcw-split { grid-template-columns: 1fr; } .dcw-timeline { grid-template-columns: repeat(5, minmax(132px, 1fr)); overflow-x: auto; } }
@media screen and (max-width: 767px) { .dcw-role-cols { grid-template-columns: 1fr; } .dcw-meta-row { grid-template-columns: 1fr; grid-row-gap: 4px; } }

.dcw-section.is-tint { background-color: #eef7f5; }
.dcw-lede { margin-top: 20px; margin-bottom: 0; color: #3d3d3d; font-size: clamp(18px, 1.6vw, 21px); line-height: 1.55; }
.dcw-mock.is-pv { max-width: 250px; }
.dcw-fig-title { margin-bottom: 3px; color: #111111; font-size: 15px; font-weight: 600; line-height: 1.35; }
.dcw-fig-text { margin-top: 10px; margin-bottom: 0; color: #5f5f5f; font-size: 14px; line-height: 1.5; }
.dcw-preview { display: grid; grid-template-columns: repeat(3, 1fr); grid-column-gap: clamp(24px, 4vw, 56px); grid-row-gap: 48px; }
.dcw-pv { display: flex; flex-direction: column; align-items: center; }
.dcw-pv-cap { width: 100%; max-width: 300px; margin-top: 16px; }
.dcw-pv-step { margin-bottom: 4px; color: #0f6e68; font-family: Inconsolata, monospace; font-size: 13px; }
@media screen and (max-width: 767px) { .dcw-preview { grid-template-columns: 1fr; } .dcw-mock.is-pv { max-width: 230px; } }
